code:
module up_down_counter_3bit (
    input wire clk,
    input wire rst,
    input wire dir,
    output reg [2:0] count
    );

always @(posedge clk) begin
    if (rst) begin
        count <= 3'b000;
    end else if (dir) begin
        count <= count + 1;
    end else begin
        count <= count - 1;
    end
end

endmodule

testbench:
`timescale 1ns/1ps

module up_down_counter_3bit_tb;

    // Testbench signals (sequential circuit)
    reg clk;
    reg dir;
    reg rst;
    wire [2:0] count;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    up_down_counter_3bit dut (
        .clk(clk),
        .dir(dir),
        .rst(rst),
        .count(count)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

    begin
        rst = 1;
        dir = 0;
        @(posedge clk);
        #1;
        rst = 0;
    end
        endtask
    task testcase001;

    begin
        test_num = 1;
        $display("Testcase %0d: Reset Check", test_num);
        reset_dut();
        #1;

        check_outputs(3'b000);
    end
        endtask

    task testcase002;

    begin
        test_num = 2;
        $display("Testcase %0d: Up-Counting Wrap Around", test_num);
        reset_dut();
        dir = 1;

        repeat (8) @(posedge clk);
        #1;
        #1;

        check_outputs(3'b000);
    end
        endtask

    task testcase003;

    begin
        test_num = 3;
        $display("Testcase %0d: Down-Counting Wrap Around", test_num);
        reset_dut();
        dir = 0;

        repeat (8) @(posedge clk);
        #1;
        #1;

        check_outputs(3'b000);
    end
        endtask

    task testcase004;

    begin
        test_num = 4;
        $display("Testcase %0d: Partial Up-Count to 5", test_num);
        reset_dut();
        dir = 1;

        repeat (5) @(posedge clk);
        #1;
        #1;

        check_outputs(3'b101);
    end
        endtask

    task testcase005;

    begin
        test_num = 5;
        $display("Testcase %0d: Direction Switching (Up then Down)", test_num);
        reset_dut();
        dir = 1;
        repeat (4) @(posedge clk);
        dir = 0;
        repeat (2) @(posedge clk);
        #1;
        #1;

        check_outputs(3'b010);
    end
        endtask

    task testcase006;

    begin
        test_num = 6;
        $display("Testcase %0d: Synchronous Reset during Up-Count", test_num);
        reset_dut();
        dir = 1;
        repeat (3) @(posedge clk);
        rst = 1;
        @(posedge clk);
        #1;
        #1;

        check_outputs(3'b000);
    end
        endtask

    task testcase007;

    begin
        test_num = 7;
        $display("Testcase %0d: Underflow Check (0 to 7)", test_num);
        reset_dut();
        dir = 0;
        @(posedge clk);
        #1;
        #1;

        check_outputs(3'b111);
    end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

        $display("========================================");
        $display("up_down_counter_3bit Testbench");
        $display("========================================");


        testcase001();
        testcase002();
        testcase003();
        testcase004();
        testcase005();
        testcase006();
        testcase007();


// Print summary
        $display("\n========================================");
        $display("Test Summary");
        $display("========================================");
        $display("Tests Passed: %0d", pass_count);
        $display("Tests Failed: %0d", fail_count);
        $display("Total Tests:  %0d", pass_count + fail_count);
        $display("========================================");

        if (fail_count == 0)
            $display("ALL TESTS PASSED!");
        else
            $display("SOME TESTS FAILED!");

        $display("\nSimulation completed at time %0t", $time);
        $finish;
    end

    // Task to check outputs
    task check_outputs;
        input [2:0] expected_count;
