    input areset,  // async active-high reset to zero
    input load,
    input ena,
    input [3:0] data,
    output reg [3:0] q);reg [3:0] shift_reg;
    reg [1:0] shift_amt;

    always @ (posedge clk or posedge areset) begin
        if (areset) begin
            shift_reg <= 4'b0;
            shift_amt <= 2'b0;
        end else begin
            if (load & ena) begin
                shift_reg <= data;
                shift_amt <= 2'b0;
            end else begin
                case (shift_amt)
                    2'b00: shift_reg <= {shift_reg[2:0], shift_reg[3]};
                    2'b01: shift_reg <= {shift_reg[1:0], shift_reg[3:2]};
                    2'b10: shift_reg <= {shift_reg[0], shift_reg[3:1]};
                    2'b11: shift_reg <= {shift_reg[3], shift_reg[2:0]};
                endcase
                if (ena) begin
                    shift_amt <= shift_amt + 1;
                end
            end
        end
    end

    assign q = shift_reg;

endmodule

