module top_module(
    input [3:0] data_in,
    input control,
    input clk,           // Added clk input
    output reg [4:0] data_out  // Changed output to reg type
);reg [3:0] shift_reg;
    reg parity_bit;

    always @(posedge clk) begin
        shift_reg <= {shift_reg[2:0], data_in};
        parity_bit <= control ? ^shift_reg : ~^shift_reg;
        data_out <= {data_in, parity_bit}; // Moved the assignment inside the always block
    end

endmodule

