description:
Design a binary to Binary-Coded Decimal (BCD) converter that transforms a 4-bit binary input (BIN) into its BCD representation. The module produces two separate outputs: BCD_HIGH for the high nibble and BCD_LOW for the low nibble, effectively representing the decimal digits corresponding to the binary input. The conversion is done using combinational logic that evaluates the value of the binary input, determining which bits of the BCD outputs should be set based on specific range conditions of the input.
module top_module(
    input [3:0] BIN,
    output [3:0] BCD_HIGH,
    output [3:0] BCD_LOW
);

code:
module top_module(
    input [3:0] BIN,
    output [3:0] BCD_HIGH,
    output [3:0] BCD_LOW
);wire [6:0] BCD;

    assign BCD = {
        (BIN >= 8) ? 1'b1 : 1'b0,
        (BIN >= 8 || BIN >= 4) ? 1'b1 : 1'b0,
        (BIN >= 8 || BIN >= 4 || BIN >= 2) ? 1'b1 : 1'b0,
        (BIN >= 8 || BIN >= 4 || BIN >= 2 || BIN >= 1) ? 1'b1 : 1'b0,
        (BIN >= 8 || BIN >= 2 || BIN >= 1) ? 1'b1 : 1'b0,
        (BIN >= 4 || BIN >= 2 || BIN >= 1) ? 1'b1 : 1'b0,
        (BIN >= 2 || BIN >= 1) ? 1'b1 : 1'b0
    };

    assign BCD_HIGH = BCD[6:3];
    assign BCD_LOW = BCD[3:0];

endmodule

