module top_module(
    aclr,
    data,
    rdclk,
    rdreq,
    wrclk,
    wrreq,
    q,
    wrusedw
);input aclr;
input [138:0] data;
input rdclk;
input rdreq;
input wrclk;
input wrreq;
output reg [138:0] q;  // Changed to reg to allow assignment in always block
output [7:0] wrusedw;

reg [138:0] mem [0:255];
reg [7:0] wr_ptr;
reg [7:0] rd_ptr;
reg [7:0] wr_used_bits;
reg [7:0] rd_used_bits;
wire [7:0] wr_unused_bits;
wire [7:0] rd_unused_bits;
wire [7:0] wr_next_ptr;
wire [7:0] rd_next_ptr;

assign wr_unused_bits = 256 - wr_used_bits;  // Correct bit size for unused bits
assign rd_unused_bits = 256 - rd_used_bits;  // Correct bit size for unused bits
assign wrusedw = wr_used_bits;

always @(posedge wrclk) begin
    if (wrreq) begin
        if (wr_used_bits < 256) begin
            mem[wr_ptr] <= data;   // Write data directly to memory
            wr_ptr <= wr_next_ptr;
            wr_used_bits <= wr_used_bits + 1;  // Increment used bits count
        end
    end
end

always @(posedge rdclk) begin
    if (rdreq) begin
        if (rd_used_bits > 0) begin
            q <= mem[rd_ptr];
            rd_ptr <= rd_next_ptr;
            rd_used_bits <= rd_used_bits - 1;  // Decrement used bits count
        end
    end
end

assign wr_next_ptr = wr_ptr + 1;  // Using continuous assignment for next pointer
assign rd_next_ptr = rd_ptr + 1;  // Using continuous assignment for next pointer

always @(posedge wrclk or posedge aclr) begin
    if (aclr) begin
        wr_ptr <= 0;
        wr_used_bits <= 0;
    end else if (wrreq && wr_used_bits < 256) begin
        // No need to set wr_ptr again here as it's handled in the write always block
    end
end

always @(posedge rdclk or posedge aclr) begin
    if (aclr) begin
        rd_ptr <= 0;
        rd_used_bits <= 0;
    end else if (rdreq && rd_used_bits > 0) begin
        // No need to set rd_ptr again here as it's handled in the read always block
    end
end

endmodule

