module up_down_counter_4bit (count, clk, reset, up_down);
   input clk, reset, up_down;
   output [3:0] count;

   reg [3:0] count;

always @(posedge clk or posedge reset) begin
    if (reset) 
    begin
        count <= 0;
    end 
    else 
    begin
        if (up_down)
            count <= count + 1;
        else
            count <= count - 1;
    end
end

endmodule

