module top_module(
		        clk    ,
		        cen_i  ,
		        wen_i  ,
		        addr_i ,
		        data_i ,		
		        data_o		        
);parameter                 Word_Width = 32;
parameter                 Addr_Width = 8;






input                     clk;      
input   		          cen_i;    
input   		          wen_i;    
input   [Addr_Width-1:0]  addr_i;   
input   [Word_Width-1:0]  data_i;   
output	[Word_Width-1:0]  data_o;   






