Design a clock divider circuit that generates a slower clock signal from an input clock. The module takes an input clock signal (clk_in) and a reset signal (rst_n), and outputs a divided clock signal (clk_out). The clock output toggles its state every 128 clock cycles of the input, effectively reducing the frequency of clk_in by a factor of 128. The reset signal asynchronously clears the counter and initializes the output clock to a LOW state when asserted.
module top_module(
	input clk_in,
	input rst_n,
	output reg clk_out
);

code:
module top_module(
	input clk_in,
	input rst_n,
	output reg clk_out
);reg [7:0]counter;

	always @(posedge clk_in or posedge rst_n) begin
		if (rst_n) begin

			counter <= 0;
			clk_out <= 0;
		end
		else if (counter == 127) begin
			counter <= 0;
			clk_out <= ~clk_out;
		end
		else begin
			counter <= counter + 1;
		end
	end
endmodule

