module top_module (
  input in1,
  input in2,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter A=0, B=1, C=2, D=3;

    always_comb begin
		case (state)
			A: next_state = in1 ? C : B;
			B: next_state = in1 ? D : C;
			C: next_state = in1 ? A : D;
			D: next_state = in1 ? B : A;
		endcase
    end

    always_comb begin
		case (state)
			A: out = (in1 || in2) ? 1 : 0;
			B: out = (in1 && ~in2) ? 0 : 1;
			C: out = (~in1 && in2) ? 1 : 0;
			D: out = (in1 && in2) ? 0 : 1;
		endcase
    end

endmodule

