  else if (pre) 
  q <= 1'b1; 
  else if ((clk == 1'b1) && (clk_pre == 1'b0)) 
  begin 
  if (ena == 1'b1) 
  begin 
  if (s && !r) 
  q <= 1'b1; 
  else if (!s && r) 
  q <= 1'b0; 
  else if (s && r) 
  q <= ~q; 
  end 
  end 
  clk_pre <= clk; 
  end 
