code:
module top_module(
    i_data0,
    o_data0
);input   [31:0] i_data0;
  output  [31:0]
    o_data0;



  wire [31:0]
    w1,
    w16,
    w17,
    w136,
    w153,
    w256,
    w103,
    w3296;

  assign w1 = i_data0;
  assign w103 = w256 - w153;
